Функция РазрешитьРегистр(ПолноеИмя) Экспорт
	Разрешенный = РазрешитьТип(ПолноеИмя);
	Если Разрешенный = Неопределено Тогда
		Возврат Неопределено;
	КонецЕсли;
	Если Не Метаданные.РегистрыСведений.Содержит(Разрешенный.metadata) Тогда
		Возврат Новый Структура("name,kind,metadata,independent,periodicity",
			Разрешенный.name, "unsupported", Разрешенный.metadata, Ложь, "");
	КонецЕсли;
	Возврат РегистрМетаданных(Разрешенный.metadata);
КонецФункции

Функция РегистрМетаданных(Мета)
	Независимый = Мета.РежимЗаписи = Метаданные.СвойстваОбъектов.РежимЗаписиРегистра.Независимый;
	Возврат Новый Структура("name,kind,metadata,independent,periodicity",
		Мета.ПолноеИмя(), "register", Мета, Независимый, ПериодичностьРегистра(Мета));
КонецФункции

Функция ПериодичностьРегистра(Мета)
	Значение = Мета.ПериодичностьРегистраСведений;
	Виды = Метаданные.СвойстваОбъектов.ПериодичностьРегистраСведений;
	Если Значение = Виды.Непериодический Тогда
		Возврат "nonperiodic";
	ИначеЕсли Значение = Виды.Секунда Тогда
		Возврат "second";
	ИначеЕсли Значение = Виды.День Тогда
		Возврат "day";
	ИначеЕсли Значение = Виды.Месяц Тогда
		Возврат "month";
	ИначеЕсли Значение = Виды.Квартал Тогда
		Возврат "quarter";
	ИначеЕсли Значение = Виды.Год Тогда
		Возврат "year";
	КонецЕсли;
	Возврат "nonperiodic";
КонецФункции

Функция ОперацииРегистра(Регистр) Экспорт
	Если Регистр.periodicity = "nonperiodic" Тогда
		Причина = "Регистр непериодический: срез на дату, история и запись с периода не применимы";
		Возврат Новый Структура("slice,history,record",
			Новый Структура("allowed,reason", Ложь, Причина),
			Новый Структура("allowed,reason", Ложь, Причина),
			Новый Структура("allowed,reason", Ложь, Причина));
	КонецЕсли;
	Чтение = ПравоДоступа("Чтение", Регистр.metadata);
	Изменение = ПравоДоступа("Изменение", Регистр.metadata);
	Возврат Новый Структура("slice,history,record",
		Новый Структура("allowed,reason", Чтение, ?(Чтение, Неопределено, "Нет права чтения регистра")),
		Новый Структура("allowed,reason", Чтение, ?(Чтение, Неопределено, "Нет права чтения регистра")),
		Новый Структура("allowed,reason", Изменение, ?(Изменение, Неопределено, "Нет права изменения регистра")));
КонецФункции

Функция ОписаниеРегистра(Регистр) Экспорт
	// Общие реквизиты конфигурации в описание регистра не входят.
	Измерения = Новый Массив;
	Для Каждого МетаПоля Из Регистр.metadata.Измерения Цикл
		Измерения.Добавить(ОписаниеПоляРегистра(МетаПоля, Истина, Ложь));
	КонецЦикла;
	Ресурсы = Новый Массив;
	Для Каждого МетаПоля Из Регистр.metadata.Ресурсы Цикл
		Ресурсы.Добавить(ОписаниеПоляРегистра(МетаПоля, Ложь, Ложь));
	КонецЦикла;
	Реквизиты = Новый Массив;
	Для Каждого МетаПоля Из Регистр.metadata.Реквизиты Цикл
		Реквизиты.Добавить(ОписаниеПоляРегистра(МетаПоля, Ложь, Истина));
	КонецЦикла;
	Возврат Новый Структура("name,title,kind,periodicity,operations,dimensions,resources,attributes,exchange,rules",
		Регистр.name, Регистр.metadata.Представление(), "register", Регистр.periodicity, ОперацииРегистра(Регистр),
		Измерения, Ресурсы, Реквизиты, ОбменРегистра(Регистр), ПравилаРегистра());
КонецФункции

Функция ОписаниеПоляРегистра(МетаПоля, ЭтоИзмерение, ЭтоРеквизит)
	Варианты = Новый Массив;
	Чтение = Ложь;
	Запись = Ложь;
	ЧастичныйЗапрет = Ложь;
	Для Каждого ТипПоля Из МетаПоля.Тип.Типы() Цикл
		Вариант = ОписаниеТипа(ТипПоля, МетаПоля.Тип);
		Варианты.Добавить(Вариант);
		Чтение = Чтение Или Вариант.readable;
		Запись = Запись Или Вариант.writable;
		ЧастичныйЗапрет = ЧастичныйЗапрет Или Не Вариант.readable Или Не Вариант.writable;
	КонецЦикла;
	Обязательно = МетаПоля.ПроверкаЗаполнения = ПроверкаЗаполнения.ВыдаватьОшибку;
	Если ЭтоИзмерение И МетаПоля.ЗапрещатьНезаполненныеЗначения Тогда
		Обязательно = Истина;
	КонецЕсли;
	Причина = Неопределено;
	Если ЭтоРеквизит Тогда
		// Контракт реквизиты не записывает: при замене значения они остаются.
		Запись = Ложь;
		Причина = "Реквизит не записывается этим контрактом и сохраняется при замене значения";
	ИначеЕсли Не Запись Тогда
		Причина = "Поле не содержит вариантов, доступных для записи";
	ИначеЕсли ЧастичныйЗапрет Тогда
		Причина = "Не все варианты значения поддерживают чтение или запись; ограничения указаны в types";
	КонецЕсли;
	Возврат Новый Структура("name,title,required,readable,writable,reason,types", МетаПоля.Имя,
		МетаПоля.Представление(), Обязательно, Чтение, Запись, Причина, Варианты);
КонецФункции

Функция ОбменРегистра(Регистр)
	Возврат Новый Структура("recordTemplate,compoundTemplate,nullRule,dateRule,periodRule,filterRule",
		Новый Структура("name,period,dimensions,resources", Регистр.name, "YYYY-MM-DDTHH:mm:ss", Новый Структура, Новый Структура),
		Новый Структура("type,value", "types[].name", Неопределено),
		"null означает штатное пустое значение типа; обязательность и запрет выбранного типа сохраняются",
		"Дата YYYY-MM-DD; дата и время YYYY-MM-DDTHH:mm:ss; время HH:mm:ss. Местное время базы, без Z и смещения",
		"Период YYYY-MM-DD или YYYY-MM-DDTHH:mm:ss приводится к началу периодичности регистра",
		"Отбор только по измерениям; пустое значение отбора не поддерживается; имена name и date зарезервированы");
КонецФункции

Функция ПравилаРегистра()
	Правила = Новый Массив;
	Правила.Добавить("Поддерживаются только независимые регистры сведений");
	Правила.Добавить("Запись заменяет значение того же периода и ключа измерений");
	Правила.Добавить("Реквизиты не записываются и сохраняются при замене");
	Правила.Добавить("Удаление записей регистра не поддерживается");
	Правила.Добавить("Отбор только по измерениям");
	Правила.Добавить("Предел выдачи 100 записей; hasMore означает, что записей больше");
	Возврат Правила;
КонецФункции

Функция ИменаИзмерений(Регистр) Экспорт
	Имена = Новый Массив;
	Для Каждого МетаПоля Из Регистр.metadata.Измерения Цикл
		Если МетаПоля.Имя <> "name" И МетаПоля.Имя <> "date" Тогда
			Имена.Добавить(МетаПоля.Имя);
		КонецЕсли;
	КонецЦикла;
	Возврат Имена;
КонецФункции

