input.new_string:
	Ошибка(Ошибки, Путь, "Ссылка некорректна, отсутствует, недоступна, помечена на удаление или является группой вне поля родителя");
	Возврат Неопределено;
КонецФункции

Функция МоментСреза(Строка) Экспорт
	Если ТипЗнч(Строка) <> Тип("Строка") Тогда
		Возврат Неопределено;
	КонецЕсли;
	Если СтрДлина(Строка) = 19 И ТекстСоответствуетМаске(Строка, "0000-00-00T00:00:00") Тогда
		Возврат ДатаISO(Строка);
	ИначеЕсли СтрДлина(Строка) = 10 И ТекстСоответствуетМаске(Строка, "0000-00-00") Тогда
		// Дата без времени — конец дня: срез «на сегодня» включает записи этого дня.
		Дата = ДатаISO(Строка + "T00:00:00");
		Если Дата = Неопределено Тогда
			Возврат Неопределено;
		КонецЕсли;
		Возврат КонецДня(Дата);
	КонецЕсли;
	Возврат Неопределено;
КонецФункции

Функция ЗначениеОтбораИзСтроки(Строка, Поле, ТипыПоля, Путь, Ошибки) Экспорт
	Если ТипЗнч(Строка) <> Тип("Строка") Или ПустаяСтрока(Строка) Тогда
		Ошибка(Ошибки, Путь, "Пустое значение отбора не поддерживается");
		Возврат Неопределено;
	КонецЕсли;
	Если Поле.types.Количество() > 1 Тогда
		Вход = ЗначениеJSON(Строка);
		Если Вход = Неопределено Или ТипЗнч(Вход) <> Тип("Соответствие") Тогда
			Ошибка(Ошибки, Путь, "Составное измерение передается объектом JSON type,value");
			Возврат Неопределено;
		КонецЕсли;
	ИначеЕсли Поле.types[0].kind = "number" Тогда
		Вход = ЗначениеJSON(Строка);
		Если ТипЗнч(Вход) <> Тип("Число") Тогда
			Ошибка(Ошибки, Путь, "Требуется число JSON");
			Возврат Неопределено;
		КонецЕсли;
	ИначеЕсли Поле.types[0].kind = "boolean" Тогда
		Если Строка = "true" Тогда
			Вход = Истина;
		ИначеЕсли Строка = "false" Тогда
			Вход = Ложь;
		Иначе
			Ошибка(Ошибки, Путь, "Требуется true или false");
			Возврат Неопределено;
		КонецЕсли;
	Иначе
		Вход = Строка;
	КонецЕсли;
	Возврат ИзJSON(Вход, Поле, ТипыПоля, "ordinary", Путь, Ошибки);
КонецФункции

Функция ЗначениеJSON(Текст)
	Попытка
		Чтение = Новый ЧтениеJSON;
