		Дата = ДатаISO(Строка);
	ИначеЕсли ТипЗнч(Строка) = Тип("Строка") И СтрДлина(Строка) = 10 И ТекстСоответствуетМаске(Строка, "0000-00-00") Тогда
		Дата = ДатаISO(Строка + "T00:00:00");
	КонецЕсли;
	Если Дата = Неопределено Тогда
		Возврат Неопределено;
	КонецЕсли;
	Если Периодичность = "second" Тогда
		Возврат Дата;
	ИначеЕсли Периодичность = "day" Тогда
		Возврат НачалоДня(Дата);
	ИначеЕсли Периодичность = "month" Тогда
