Функция ПодготовитьЗаписьРегистра(Данные, Регистр, Описание, Ошибки) Экспорт
	Результат = Новый Структура("period,dimensions,resources", Неопределено, Новый Соответствие, Новый Соответствие);
	Если ТипЗнч(Данные) <> Тип("Соответствие") Тогда
		Ошибка(Ошибки, Неопределено, "Корень должен быть объектом JSON");
		Возврат Результат;
	КонецЕсли;
	Допустимые = СтрРазделить("name,period,dimensions,resources", ",");
	Для Каждого Пара Из Данные Цикл
		Если Допустимые.Найти(Пара.Ключ) = Неопределено Тогда
			Ошибка(Ошибки, Пара.Ключ, "Неизвестное поле корня");
		КонецЕсли;
	КонецЦикла;
	Если Не СчетаМагазинаЗначения.ЕстьКлюч(Данные, "name") Или ТипЗнч(Данные.Получить("name")) <> Тип("Строка") Тогда
		Ошибка(Ошибки, "name", "Отсутствует обязательное поле или неверный тип JSON");
	КонецЕсли;
	Если Не СчетаМагазинаЗначения.ЕстьКлюч(Данные, "period") Или ТипЗнч(Данные.Получить("period")) <> Тип("Строка") Тогда
		Ошибка(Ошибки, "period", "Отсутствует обязательное поле или неверный тип JSON");
	Иначе
		Период = СчетаМагазинаЗначения.НачалоПериода(Данные.Получить("period"), Регистр.periodicity);
		Если Период = Неопределено Тогда
			Ошибка(Ошибки, "period", "Неверный период: требуется YYYY-MM-DD или YYYY-MM-DDTHH:mm:ss");
		Иначе
			Результат.period = Период;
		КонецЕсли;
	КонецЕсли;
	Результат.dimensions = ПодготовитьРазделЗаписи(Данные, "dimensions", Описание.dimensions, Регистр.metadata.Измерения, Истина, Ошибки);
	Результат.resources = ПодготовитьРазделЗаписи(Данные, "resources", Описание.resources, Регистр.metadata.Ресурсы, Ложь, Ошибки);
	Возврат Результат;
КонецФункции

Функция ПодготовитьРазделЗаписи(Данные, ИмяРаздела, Описания, МетаКоллекция, ЭтоИзмерение, Ошибки)
	Результат = Новый Соответствие;
	Если Не СчетаМагазинаЗначения.ЕстьКлюч(Данные, ИмяРаздела) Или ТипЗнч(Данные.Получить(ИмяРаздела)) <> Тип("Соответствие") Тогда
		Ошибка(Ошибки, ИмяРаздела, "Отсутствует обязательное поле или неверный тип JSON");
		Возврат Результат;
	КонецЕсли;
	Раздел = Данные.Получить(ИмяРаздела);
	Для Каждого Пара Из Раздел Цикл
		Если СчетаМагазинаМетаданные.НайтиОписание(Описания, Пара.Ключ) = Неопределено Тогда
			Ошибка(Ошибки, ИмяРаздела + "." + Пара.Ключ, "Неизвестное поле");
		КонецЕсли;
	КонецЦикла;
	Для Каждого Поле Из Описания Цикл
		Путь = ИмяРаздела + "." + Поле.name;
		Если Не СчетаМагазинаЗначения.ЕстьКлюч(Раздел, Поле.name) Тогда
			Ошибка(Ошибки, Путь, "Отсутствует обязательное поле");
			Продолжить;
		КонецЕсли;
		МетаПоля = МетаКоллекция.Найти(Поле.name);
		БылоОшибок = Ошибки.Количество();
		Значение = СчетаМагазинаЗначения.ИзJSON(Раздел.Получить(Поле.name), Поле, МетаПоля.Тип, "ordinary", Путь, Ошибки);
		Если Ошибки.Количество() <> БылоОшибок Тогда
			Продолжить;
		КонецЕсли;
		Если ЭтоИзмерение И Поле.required И ПустоеЗначение(Значение) Тогда
			Ошибка(Ошибки, Путь, "Пустое обязательное измерение");
			Продолжить;
		КонецЕсли;
		Результат.Вставить(Поле.name, Значение);
	КонецЦикла;
	Возврат Результат;
КонецФункции

Функция ПустоеЗначение(Значение)
	Если Значение = Неопределено Или ТипЗнч(Значение) = Тип("Булево") Или ТипЗнч(Значение) = Тип("Число") Тогда
		Возврат Значение = Неопределено;
	КонецЕсли;
	Возврат Не ЗначениеЗаполнено(Значение);
КонецФункции

Функция НаборЗаписиРегистра(Регистр, Подготовленные) Экспорт
	Набор = РегистрыСведений[Регистр.metadata.Имя].СоздатьНаборЗаписей();
	Набор.Отбор.Период.Установить(Подготовленные.period);
	Для Каждого Пара Из Подготовленные.dimensions Цикл
		Набор.Отбор[Пара.Ключ].Установить(Пара.Значение);
	КонецЦикла;
	Набор.Прочитать();
	// Реквизиты прочитанной записи не трогаем: замена переписывает только ресурсы.
	Заменена = Набор.Количество() > 0;
	Если Заменена Тогда
		Для Каждого Запись Из Набор Цикл
			Для Каждого Пара Из Подготовленные.resources Цикл
				Запись[Пара.Ключ] = Пара.Значение;
			КонецЦикла;
		КонецЦикла;
	Иначе
		Запись = Набор.Добавить();
		Запись.Период = Подготовленные.period;
		Для Каждого Пара Из Подготовленные.dimensions Цикл
			Запись[Пара.Ключ] = Пара.Значение;
		КонецЦикла;
		Для Каждого Пара Из Подготовленные.resources Цикл
			Запись[Пара.Ключ] = Пара.Значение;
		КонецЦикла;
	КонецЕсли;
	Возврат Новый Структура("set,replaced", Набор, Заменена);
КонецФункции

